#include <cplib/utils/oeis.hpp>
using namespace cplib;
int main(){std::vector<std::string> queries;auto fetch=[&](const std::string& q){queries.push_back(q);return std::string(R"({"results":[{"number":45,"name":"Fibonacci \u6570\u5217","data":"0,1,1,2,3,5"},{"number":7},{"name":"skip"}]})");};auto out=searchOEIS(std::vector<Int>{0,1,1,2,3},fetch);assert(queries==std::vector<std::string>{"0,1,1,2,3"});assert(out.size()==2&&out[0].id=="A000045"&&out[0].name=="Fibonacci 数列"&&out[0].kind==oeisSequence);assert(to_string(out[0]).find("https://oeis.org/A000045")!=std::string::npos);queries.clear();out=searchOEIS(std::vector<std::vector<Int>>{{1,2,3},{4},{5,6}},fetch);assert((queries==std::vector<std::string>{"1,2,3,4,5,6","1,2,4,3,5,6"}));assert(out[0].kind==oeisMatrixRowMajor&&out[2].kind==oeisMatrixAntidiagonal);queries.clear();out=searchOEIS(std::vector<Fraction<Int>>{{2,4},{-3,-9}},fetch);assert((queries==std::vector<std::string>{"1,1","2,3"}));assert(out[0].kind==oeisNumerator&&out[2].kind==oeisDenominator);assert(searchOEIS(std::vector<Int>{},fetch).empty());for(auto body:{"null","{}","{\"results\":null}","[]"})assert(detail::oeis::parse(body,"1",oeisSequence).empty());assert(detail::oeis::parse("[{\"number\":123}]","1",oeisSequence)[0].id=="A000123");}
